import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";

export type MessagesResponseToolUseBlock = {
  /** Content block type. @default "tool_use" */
  type?: "tool_use";
  /** Identifier of the tool call emitted by the model. */
  id: string;
  /** Name of the invoked tool. */
  name: string;
  /** Parsed tool argument object generated by the model. */
  input: Record<string, unknown>;
};

export const messagesResponseToolUseBlockSchema: Schema<MessagesResponseToolUseBlock> =
  s.object<MessagesResponseToolUseBlock>({
    type: s.defaulted(s.literal("tool_use"), "tool_use"),
    id: s.string(),
    name: s.string(),
    input: s.record(s.string(), s.unknown()),
  });
